        return (None, errors)

    # Determine a unique backup directory.
    backup_dir = get_unique_backup_dir(source_dir)

    # Try to copy the source directory into the backup folder.
    try:
        shutil.copytree(source_dir, backup_dir)
    except Exception as e:
        errors.append(str(e))

    # Try to remove the original directory.
    try:
        shutil.rmtree(source_dir)
    except Exception as e:
        errors.append(str(e))

    return (backup_dir, errors)


